// Bundled Inter ExtraBold TTF Font for Serverless Resvg Rendering
import fs from 'fs';
import os from 'os';
import path from 'path';

const FONT_BASE64 = '';

let cachedFontPath: string | null = null;

export function ensureFontFile(): string {
  if (cachedFontPath && fs.existsSync(cachedFontPath)) {
    return cachedFontPath;
  }
  const targetPath = path.join(os.tmpdir(), 'bpc-inter-extrabold.ttf');
  if (!fs.existsSync(targetPath)) {
    fs.writeFileSync(targetPath, Buffer.from(FONT_BASE64, 'base64'));
  }
  cachedFontPath = targetPath;
  return targetPath;
}
